          image: 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w5MjI2ODB8MHwxfHNlYXJjaHwyfHxqYXBhbiUyMGxpZmVzdHlsZXxlbnwwfDB8fHwxNzgwMDk2MjA4fDA&ixlib=rb-4.1.0&q=80&w=1080',
          imageAlt: 'two women in purple and pink kimono standing on street',
